shader:
#version 300 es
precision highp float;
uniform float u_time;
uniform vec2 u_resolution;
uniform float u_audio[8];
uniform float u_seed;
uniform vec3 u_palette[4];
uniform float u_params[8];
out vec4 fragColor;
void main(){vec2 p=(gl_FragCoord.xy-.5*u_resolution)/min(u_resolution.x,u_resolution.y)*2.0/u_params[1];p.x=abs(p.x);float a=atan(p.y,p.x);float d=abs(sin(a*7.0+length(p)*22.0-u_time*.4));float glow=exp(-d*24.0)*exp(-dot(p,p)*1.3)*u_params[0];vec3 col=mix(u_palette[0],u_palette[1],clamp(u_audio[1]+u_audio[2]*.4,0.0,1.0));fragColor=vec4(col*glow,clamp(glow*.65,0.0,.85));}
